package com.dispatchpro.driver;
import android.app.*;
import android.content.*;
import android.os.Build;
import java.util.*;
public final class CustomerChatNotifications{
 public static synchronized void show(Context context,String event){if(event==null||!event.matches("[a-fA-F0-9-]{36}"))return;if(Build.VERSION.SDK_INT>=33&&context.checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)return;NotificationManager manager=context.getSystemService(NotificationManager.class);if(!manager.areNotificationsEnabled())return;android.content.SharedPreferences store=context.getSharedPreferences("customer-chat",0);Set<String> seen=new LinkedHashSet<>(store.getStringSet("seen",new LinkedHashSet<>()));if(!seen.add(event))return;while(seen.size()>256)seen.remove(seen.iterator().next());if(!store.edit().putStringSet("seen",seen).commit())return;String channel="customer_chat_v1";if(Build.VERSION.SDK_INT>=26)manager.createNotificationChannel(new NotificationChannel(channel,"رسائل الرحلة",NotificationManager.IMPORTANCE_HIGH));PendingIntent open=PendingIntent.getActivity(context,0,new Intent(context,CustomerActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder builder=Build.VERSION.SDK_INT>=26?new Notification.Builder(context,channel):new Notification.Builder(context);builder.setSmallIcon(R.drawable.ic_driver).setContentTitle("رسالة جديدة من السائق").setContentText("افتح المحادثة للاطلاع على الرسالة.").setContentIntent(open).setAutoCancel(true).setVisibility(Notification.VISIBILITY_PRIVATE);if(Build.VERSION.SDK_INT<26)builder.setPriority(Notification.PRIORITY_HIGH).setDefaults(Notification.DEFAULT_SOUND|Notification.DEFAULT_VIBRATE);manager.notify(event,1,builder.build());}
}
